from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-200, 200, timedelta(0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.closes = RollingWindow[float](21)
        self.pending_signal_time = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiry_date = None
        self.time_stop_date = None
        self.block_entries_date = None
        self.equity_exit_ticket = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour == 9 and end_time.minute >= 45)
            or (10 <= end_time.hour <= 13)
            or (end_time.hour == 14 and end_time.minute <= 30)
        )

        if eligible_time and previous_fast <= previous_slow and current_fast > current_slow:
            self.pending_signal_time = end_time

    def OnData(self, data):
        today = self.Time.date()

        # Handle an unexpected equity position caused by option exercise/assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            if self.equity_exit_ticket is None or self.equity_exit_ticket.Status in (
                OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
            ):
                self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
                self.equity_exit_ticket = self.MarketOrder(self.spy, -spy_quantity)
            return

        if self.held_symbol is not None:
            self.ManageHeldOption(data, today)

        if self.pending_signal_time is not None:
            signal_time = self.pending_signal_time
            self.pending_signal_time = None

            if self.Time == signal_time:
                self.TryEnter(data, today)

    def TryEnter(self, data, today):
        if self.block_entries_date == today:
            return

        if self.held_symbol is not None or self.entry_ticket is not None:
            return

        if self.Portfolio[self.spy].Invested:
            return

        if len(data.OptionChains) == 0:
            self.Debug("Entry skipped: no option chain in current Slice.")
            return

        chain = None
        for candidate in data.OptionChains.Values:
            if candidate.Underlying is not None and candidate.Underlying.Symbol == self.spy:
                chain = candidate
                break

        if chain is None:
            self.Debug("Entry skipped: SPY option chain unavailable.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration at least seven calendar days away.")
            return

        expiry = eligible_expirations[0]
        minimum_strike = 1.01 * spy_price

        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not contracts:
            self.Debug("Entry skipped: no qualifying call strike.")
            return

        selected = sorted(
            contracts,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, expiry, selected.Strike
            )
        )

    def ManageHeldOption(self, data, today):
        if self.expiry_date is not None and today >= self.expiry_date:
            self.block_entries_date = today
            if self.Portfolio[self.held_symbol].Quantity != 0:
                self.Debug("Expiration processing: liquidating held option.")
                self.SubmitExit("expiration")
            return

        if (
            self.time_stop_date is not None
            and today == self.time_stop_date
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.Debug("Time-stop exit submitted.")
            self.SubmitExit("time stop")
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        quote = data.QuoteBars[self.held_symbol] if self.held_symbol in data.QuoteBars else None
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.Debug("Profit-target exit submitted.")
            self.SubmitExit("profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status not in (
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        ):
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id, "Replacing with {0} exit".format(reason))

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiry_date = order_event.Symbol.ID.Date.date()
                self.time_stop_date = self.PreviousTradingDay(self.expiry_date)
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_ticket = None
                self.Debug("Entry order did not fill.")

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled: {0}".format(order_event.Symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.expiry_date = None
                self.time_stop_date = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

        if order_event.Symbol == self.spy and self.Portfolio[self.spy].Quantity != 0:
            if self.equity_exit_ticket is None:
                self.Debug("Unexpected SPY exercise/assignment order event; liquidating.")
                self.equity_exit_ticket = self.MarketOrder(
                    self.spy, -self.Portfolio[self.spy].Quantity
                )

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

