            self._handle_time_stop()
            self._handle_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._update_five_minute_bar(bar, slice)

    def _update_five_minute_bar(self, bar, slice):
        end_time = bar.EndTime.replace(second=0, microsecond=0)
        bucket_end = end_time + timedelta(minutes=(5 - end_time.minute % 5) % 5)

        if self.bucket_end is None or bucket_end != self.bucket_end:
            self.bucket_end = bucket_end
            self.bucket_closes = []
            self.last_minute_end = None

        consecutive = (
            self.last_minute_end is None or
            end_time == self.last_minute_end + timedelta(minutes=1)
        )

        if not consecutive:
            self.bucket_closes = []

        self.bucket_closes.append(bar.Close)
        self.last_minute_end = end_time

        if end_time != self.bucket_end:
            return

        is_complete = (
            len(self.bucket_closes) == 5 and
            end_time == self.bucket_end and
            self.bucket_end.time().hour >= 9
        )

        if is_complete:
            self._on_completed_five_minute_bar(self.bucket_closes[-1], self.bucket_end, slice)

        self.bucket_closes = []
        self.last_minute_end = None

    def _on_completed_five_minute_bar(self, close, bar_end, slice):
        if len(self.five_minute_closes) >= 20:
            self.five_minute_closes.pop(0)
        self.five_minute_closes.append(close)

        if len(self.five_minute_closes) < 20:
            return

        fast = sum(self.five_minute_closes[-5:]) / 5.0
        slow = sum(self.five_minute_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        time_of_day = bar_end.time()
        if time_of_day < self.Time.replace(hour=9, minute=45, second=0, microsecond=0).time():
            return
        if time_of_day > self.Time.replace(hour=14, minute=30, second=0, microsecond=0).time():
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        self._enter_call(slice)

    def _enter_call(self, slice):
        if self.option_symbol not in slice.OptionChains:
            self.Debug("Entry skipped: no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        today = self.Time.date()
        spot = self.Securities[self.spy].Price

        if spot <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        ]

        if not eligible:
            self.Debug("Entry skipped: no expiration at least 7 calendar days out.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible)
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish five-minute crossover entry")
        self.entry_order_id = ticket.OrderId
        self.Debug("Entry submitted: {0}".format(selected.Symbol))

    def _handle_profit_target(self, slice):
        if self.entry_fill_price is None or self._has_open_exit_order():
            return

        if self.held_contract not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("Profit target exit")

    def _handle_time_stop(self):
        if self.held_expiry_date is None or self._has_open_exit_order():
            return

        prior_trading_day = self._previous_spy_trading_day(self.held_expiry_date)
        if (
            self.Time.date() == prior_trading_day and
            self.Time.hour == 15 and
            self.Time.minute == 45
        ):
            self._submit_exit("Pre-expiration 15:45 exit")

    def _handle_expiration_protection(self):
        if self.held_expiry_date is None or self._has_open_exit_order():
            return

        if self.Time.date() >= self.held_expiry_date:
            self.no_entry_date = self.Time.date()
            self.Debug("Expiration protection: liquidating held option.")
            self._submit_exit("Expiration protection exit")

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, "Replacing open exit order")

        ticket = self.MarketOrder(self.held_contract, -quantity, tag=reason)
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted: {0}".format(reason))

    def _has_open_exit_order(self):
        if self.exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.exit_order_id)
        if order is None:
            return False

        return order.Status in [OrderStatus.New, OrderStatus.Submitted, OrderStatus.PartiallyFilled]

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY exercise/assignment position: liquidating.")
            self.Liquidate(self.spy, tag="Unexpected exercise/assignment liquidation")

    def OnOrderEvent(self, order_event):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.held_expiry_date = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug("Entry order canceled or invalid.")

        if self.exit_order_id == order_event.OrderId:
