                self.Debug(f"Entry failed for {self._held_contract}: {orderEvent.Status}")
                self._held_contract = None
                self._entry_price = None
                self._entry_ticket = None

        if self._exit_ticket is not None and orderEvent.OrderId == self._exit_ticket.OrderId:
