            self.Debug(
                f"Skipped entry at {self.Time}: no qualifying call for {selected_expiry}"
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self._held_contract = selected.Symbol
        self._entry_price = None
        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Submitted entry for {selected.Symbol}, strike {selected.Strike}, "
            f"expiry {selected_expiry}"
        )

    def _check_profit_target(self, data: Slice):
        if self._entry_price is None or self._exit_order_open():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self._held_contract),
            None
        )
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self._entry_price:
            self.Debug(
                f"Profit target exit for {self._held_contract}: midpoint {midpoint:.2f}"
            )
            self._submit_exit("profit target")

    def _check_time_stop(self, expiry_date):
        if self._exit_order_open():
            return

        if self.Time.hour != 15 or self.Time.minute != 45:
            return

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        previous_trading_day = exchange_hours.GetPreviousTradingDay(expiry_date)

        if self.Time.date() == previous_trading_day.date():
            self.Debug(f"Time-stop exit for {self._held_contract} at {self.Time}")
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self._held_contract is None or not self._has_option_position():
            return

        for order in self.Transactions.GetOpenOrders(self._held_contract):
            self.Transactions.CancelOrder(order.Id, f"Replacing open exit: {reason}")

        quantity = -self.Portfolio[self._held_contract].Quantity
        if quantity != 0:
            self._exit_ticket = self.MarketOrder(self._held_contract, quantity)

    def _liquidate_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Invested:
            quantity = -self.Portfolio[self.spy].Quantity
            self.Debug(
                f"Unexpected SPY exercise/assignment position; liquidating {quantity} shares"
            )
            self.MarketOrder(self.spy, quantity)

    def _has_option_position(self):
        return (
            self._held_contract is not None
            and self.Portfolio[self._held_contract].Quantity != 0
        )

    def _entry_order_open(self):
        return (
            self._entry_ticket is not None
            and self._entry_ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]
        )

    def _exit_order_open(self):
        return (
            self._exit_ticket is not None
            and self._exit_ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]
        )

