        if self.held_option is not None or self.Portfolio[self.spy].Invested:
            return

        if self.entry_order_id is not None:
            return

        option_chain = data.OptionChains.get(self.option_symbol)
        if option_chain is None:
            self.Debug("Entry skipped: no SPY option chain.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted(
            {
                contract.Expiry.date()
                for contract in option_chain
                if contract.Right == OptionRight.Call
                and contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expiries:
            self.Debug("Entry skipped: no eligible expiration.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in option_chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no eligible call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} expiry {selected_expiry} "
            f"strike {selected.Strike}"
        )

    def EvaluateExit(self, data):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        if self.HasOpenExitOrder():
            return

        expiry = self.held_option.ID.Date.date()
        preceding_trading_day = self.PreviousTradingDay(expiry)

        if (
            self.Time.date() == preceding_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.SubmitExit("time stop")
            return

        quote = data.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0 or self.entry_price is None or self.entry_price <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("profit target")

    def HandleExpirationProcessing(self):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        expiry = self.held_option.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entry_dates.add(self.Time.date())
            if not self.HasOpenExitOrder():
                self.SubmitExit("expiration protection")

    def HandleUnexpectedSpyPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if not any(order.Symbol == self.spy for order in self.Transactions.GetOpenOrders()):
            quantity = self.Portfolio[self.spy].Quantity
            self.MarketOrder(self.spy, -quantity)
            self.Debug("Unexpected SPY exercise/assignment position liquidated.")

    def SubmitExit(self, reason):
        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id, "Replacing exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.MarketOrder(self.held_option, -quantity)
            self.Debug(f"Exit submitted: {reason} for {self.held_option}")

    def HasOpenExitOrder(self):
        return (
            self.held_option is not None
            and len(self.Transactions.GetOpenOrders(self.held_option)) > 0
        )

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            if (
                self.entry_order_id is not None
                and order_event.OrderId == self.entry_order_id
                and order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid)
            ):
                self.entry_order_id = None
            return

        if self.entry_order_id is not None and order_event.OrderId == self.entry_order_id:
            self.held_option = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.entry_order_id = None
            self.Debug(
                f"Entry filled: {self.held_option} at {self.entry_price:.2f}"
            )
            return

        if self.held_option is not None and order_event.Symbol == self.held_option:
            if not self.Portfolio[self.held_option].Invested:
                self.Debug(f"Exit filled: {self.held_option} at {order_event.FillPrice:.2f}")
                self.held_option = None
                self.entry_price = None
